import Foundation

/// A 1° land/sea grid of the world (Natural Earth 1:50m land, public domain),
/// used to draw dot-matrix maps without map tiles — so journeys render the
/// same on screen, in exported images and in GIF frames.
public enum WorldMap {
    public static let columns = 360
    public static let rows = 140
    /// Latitude of the grid's top edge; rows run south to 60°S.
    public static let north = 80.0

    /// One bit per cell, row-major from the north-west corner.
    static let bits: [UInt8] = Array(Data(base64Encoded: landMask) ?? Data())

    public static func isLand(row: Int, column: Int) -> Bool {
        guard row >= 0, row < rows else { return false }
        let col = ((column % columns) + columns) % columns
        let index = row * columns + col
        guard index / 8 < bits.count else { return false }
        return bits[index / 8] & (0x80 >> UInt8(index % 8)) != 0
    }

    public static func isLand(_ c: Coordinate) -> Bool {
        let row = Int((north - c.latitude).rounded(.down))
        let column = Int((c.longitude + 180).rounded(.down))
        return isLand(row: row, column: column)
    }

    public struct Dot: Hashable, Sendable {
        /// Unit coordinates inside the viewport (0…1, y down).
        public var x: Double
        public var y: Double
    }

    /// Land dots inside `viewport`, about `targetColumns` across, evenly
    /// spaced on screen.
    public static func dots(in viewport: GeoViewport, targetColumns: Int = 64) -> (dots: [Dot], spacing: Double) {
        let step = max(1.0, (viewport.lonSpan / Double(max(targetColumns, 8))).rounded())
        let midLat = (viewport.minLat + viewport.maxLat) / 2
        let k = max(cos(midLat * .pi / 180), 0.35)
        let latStep = step * k
        var out: [Dot] = []
        var lat = (viewport.maxLat / latStep).rounded(.down) * latStep
        while lat >= viewport.minLat {
            var lon = (viewport.minLon / step).rounded(.up) * step
            while lon <= viewport.maxLon {
                var wrapped = lon
                while wrapped >= 180 { wrapped -= 360 }
                while wrapped < -180 { wrapped += 360 }
                if isLand(Coordinate(lat, wrapped)) {
                    let p = viewport.project(Coordinate(lat, lon))
                    out.append(Dot(x: p.x, y: p.y))
                }
                lon += step
            }
            lat -= latStep
        }
        return (out, step / viewport.lonSpan)
    }

    static let landMask = ""
}
